class Solution {
public:
    int minRemoval(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        int best = 1;
        int j = 0;
        for (int i = 0; i < n; i++) {
            long long limit = (long long)k * nums[i];
            while (j < n && nums[j] <= limit) j++;
            if (j - i > best) best = j - i;
        }
        return n - best;
    }
};
